            "success"
        }]
        .clone();
    }
    let text = inspect(command, "--help");
    let tail = text
        .split_once(label)
        .expect("schema section exists")
        .1
        .trim_start();
    serde_json::Deserializer::from_str(tail)
        .into_iter::<Value>()
        .next()
        .unwrap()
        .unwrap()
